INSERT INTO "persons" VALUES(4181,'person_000a','龙树',NULL,'Nāgārjuna','Nagarjuna',NULL,NULL,'华严宗远祖（八宗共祖）','patriarch',150,250,'古印度','大乘中观学派创始人。据传入龙宫取回《华严经》下本十万偈流传人间。造《十住毗婆沙论》（《十地品》注释，又称《大不思议论》），被华严宗奉为法统源头。','华严宗远祖',0,'["十住毗婆沙论", "中论"]',NULL,NULL,'《龙树菩萨传》《华严经传记》/学界推定（约150-250）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4182,'person_000b','世亲',NULL,'Vasubandhu','Vasubandhu',NULL,NULL,'唯识宗祖师','scholar',NULL,NULL,'古印度','古印度唯识学派大师。造《十地经论》十二卷，系统注释《华严经·十地品》，其「六相」等名相创新深刻影响华严宗教学。汉译催生了南北朝地论师学派。',NULL,NULL,'["十地经论", "唯识三十颂"]',NULL,NULL,'真谛译《婆薮盘豆法师传》(T50n2049)、《十地经论 卷首序》(T26n1522)',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4183,'person_001','杜顺',NULL,NULL,'Dushun',NULL,'["法顺", "帝心尊者"]','华严初祖','patriarch',557,640,'唐','华严宗初祖。雍州万年人。年十八出家于因圣寺。以《华严法界观门》开创华严宗观法体系。唐太宗赐号''帝心''。','华严五祖',1,'["华严法界观门", "华严五教止观"]','{"华严法界观门": "https://cbeta.buddhism.org.hk/xml/T45/T45n1884_001.xml", "华严五教止观": "https://cbeta.buddhism.org.hk/xml/T45/T45n1867_001.xml"}',NULL,'《续高僧传》卷二十五',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4184,'person_002','智俨',NULL,NULL,'Zhiyan',NULL,'["至相尊者", "云华尊者"]','华严二祖','patriarch',602,668,'唐','华严宗二祖。天水人。从杜顺出家，后于至相寺从慧光学华严。著《华严经搜玄记》开华严宗经疏之先河，为法藏之师。','华严五祖',2,'["华严经搜玄记", "华严一乘十玄门", "华严五十要问答"]','{"华严经搜玄记": "https://cbeta.buddhism.org.hk/xml/T35/T35n1732_001.xml", "华严一乘十玄门": "https://cbeta.buddhism.org.hk/xml/T45/T45n1868_001.xml", "华严五十要问答": "https://cbeta.buddhism.org.hk/xml/T45/T45n1869_001.xml"}',NULL,'《宋高僧传》卷五',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4185,'person_003','法藏',NULL,'Dharmamitra','Fazang',NULL,'["贤首国师", "贤首大师", "香象大师", "康藏国师"]','华严三祖·实际创立者','patriarch',643,712,'唐','华严宗实际创立者。祖籍康居，生于长安。从智俨学《华严》。参与实叉难陀译场。武则天赐号''贤首''。系统化''五教十宗''判教与''法界观门''观法。讲说《华严经》三十余遍。','华严五祖',3,'["华严一乘教义分齐章（五教章）", "华严经探玄记", "华严经义海百门", "华严金师子章", "大乘起信论义记", "十二门论宗致义记"]','{"华严一乘教义分齐章（五教章）": "https://cbeta.buddhism.org.hk/xml/T45/T45n1866_001.xml", "华严经探玄记": "https://cbeta.buddhism.org.hk/xml/T35/T35n1733_001.xml", "华严经义海百门": "https://cbeta.buddhism.org.hk/xml/T45/T45n1875_001.xml", "华严金师子章": "https://cbeta.buddhism.org.hk/xml/T45/T45n1880_001.xml", "大乘起信论义记": "https://cbeta.buddhism.org.hk/xml/T44/T44n1846_001.xml", "十二门论宗致义记": "https://cbeta.buddhism.org.hk/xml/T42/T42n1826_001.xml"}','["译师"]','《宋高僧传》卷五',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4186,'person_004','澄观',NULL,NULL,'Chengguan',NULL,'["清凉国师", "清凉大师", "大统国师"]','华严四祖·集大成者','patriarch',738,839,'唐','华严宗四祖。越州山阴人。历学律、禅、三论、天台、华严诸宗。著《华严经疏》六十卷、《演义钞》九十卷，为华严教学集大成者。历七帝之师。德宗赐号''清凉''。','华严五祖',4,'["华严经疏（华严大疏）", "华严经随疏演义钞", "华严法界玄镜", "三圣圆融观门"]','{"华严经疏（华严大疏）": "https://cbeta.buddhism.org.hk/xml/T35/T35n1735_001.xml", "华严经随疏演义钞": "https://cbeta.buddhism.org.hk/xml/T36/T36n1736_001.xml", "华严法界玄镜": "https://cbeta.buddhism.org.hk/xml/T45/T45n1883_001.xml", "三圣圆融观门": "https://cbeta.buddhism.org.hk/xml/T45/T45n1882_001.xml"}',NULL,'《宋高僧传》卷五',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4187,'person_005','宗密',NULL,NULL,'Zongmi',NULL,'["圭峰大师", "定慧禅师"]','华严五祖·禅教融合者','patriarch',780,841,'唐','华严宗五祖。果州西充人。初习儒学，后从遂州道圆禅师出家（禅宗荷泽系）。后遇澄观受学华严。融合禅教，著《禅源诸诠集都序》《华严原人论》。','华严五祖',5,'["注华严法界观门", "禅源诸诠集都序", "圆觉经大疏释义钞", "华严原人论", "华严经行愿品疏钞"]','{"注华严法界观门": "https://cbeta.buddhism.org.hk/xml/T45/T45n1884_001.xml", "禅源诸诠集都序": "https://cbeta.buddhism.org.hk/xml/T48/T48n2015_001.xml", "圆觉经大疏释义钞": "https://cbeta.buddhism.org.hk/xml/X09/X09n0245_001.xml", "华严原人论": "https://cbeta.buddhism.org.hk/xml/T45/T45n1886_001.xml", "华严经行愿品疏钞": "https://cbeta.buddhism.org.hk/xml/X05/X05n0229_001.xml"}',NULL,'《宋高僧传》卷六',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4188,'person_006','佛驮跋陀罗',NULL,'Buddhabhadra','Buddhabhadra',NULL,'["觉贤", "佛度跋陀罗"]','六十华严译者','translator',359,429,'东晋','北天竺迦毗罗卫国人。来华译经大师，于建康道场寺译出《六十华严》（旧华严），共七处八会三十四品。还译《大般泥洹经》等。',NULL,NULL,'["大方广佛华严经（六十华严，T09n0278）"]',NULL,NULL,'《高僧传》卷二',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4189,'person_007','实叉难陀',NULL,'Śikṣānanda','Śikṣānanda',NULL,'["学喜", "施乞叉难陀"]','八十华严译者','translator',652,710,'唐','于阗国（今新疆和田）人。奉武则天命来华，主译八十卷《华严经》（T10n0279），法藏曾参与其译场证义。还译《大乘入楞伽经》《大方广普贤所说经》（T10n0298）等。',NULL,NULL,'["大方广佛华严经（八十华严，T10n0279）", "大方广普贤所说经（T10n0298）"]',NULL,NULL,'《宋高僧传》卷二',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4190,'person_007b','支娄迦谶',NULL,'Lokakṣema','Lokaksema',NULL,'["支谶"]','最早汉译华严经文者','translator',NULL,NULL,'后汉','月氏国人。后汉桓帝时来华。译出《佛说兜沙经》（T10n0280），为《华严经》中最早被翻译过来的单行经（对应《如来名号品》）。',NULL,NULL,'["佛说兜沙经（T10n0280）"]',NULL,NULL,'《高僧传》卷一',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4191,'person_008','般若',NULL,'Prajñā','Prajñā',NULL,'["般若三藏"]','四十华严译者','translator',NULL,NULL,'唐','罽宾国（今克什米尔）人。唐贞元年间来华，译出《四十华严》（T10n0293），即全本《入法界品》。文末《普贤菩萨行愿赞》为藏汉佛教共同尊奉。',NULL,NULL,'["大方广佛华严经（四十华严，T10n0293）"]',NULL,NULL,'《宋高僧传》卷三',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4192,'person_009','李通玄',NULL,NULL,'Li Tongxuan',NULL,'["枣柏大师", "李长者", "显首"]','华严居士学者','scholar',635,730,'唐','唐代华严学重要在家学者。深通儒释，专精《华严》，于方山著《新华严经论》四十卷。以《易经》融会华严，方法独树一帜。','李通玄系',1,'["新华严经论", "华严经决疑论"]','{"新华严经论": "https://cbeta.buddhism.org.hk/xml/T36/T36n1739_001.xml", "华严经决疑论": "https://cbeta.buddhism.org.hk/xml/T36/T36n1741_001.xml"}',NULL,'《宋高僧传》卷二十二',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4193,'person_010','义天',NULL,NULL,'Uicheon',NULL,'["大觉国师", "义天僧统"]','高丽华严初祖','scholar',1055,1101,'宋','高丽文宗第四子。入宋求法于杭州慧因寺，从净源法师受华严教法。回国后编《新编诸宗教藏总录》（义天录），为华严文献学的奠基性著作。','高丽华严',1,'["新编诸宗教藏总录（义天录）", "圆宗文类"]',NULL,NULL,'《高丽史》卷九十',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4194,'person_011','净源',NULL,NULL,'Jingyuan',NULL,'["晋水净源"]','宋代华严中兴之祖','patriarch',1011,1088,'宋','宋代华严宗重要复兴者。住杭州慧因寺。传法于高丽义天，义天归国后送金书《华严经》三种译本供养慧因寺。慧因寺世称''华严第一道场''。','华严五祖',NULL,'["华严经疏注", "华严妄尽还源观疏"]',NULL,NULL,'《佛祖统纪》卷二十九',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4195,'person_012','月霞',NULL,NULL,'Yuexia',NULL,'["月霞长老"]','近现代华严复兴先驱','patriarch',1858,1917,'清','清末民初华严宗复兴的关键人物。于常熟兴福寺创立华严大学（1914年），为中国近代第一所华严专宗教育机构，培养了一批现代华严学僧。','月霞系',1,NULL,NULL,NULL,'于凌波《中国近现代佛教人物志》〈华严宗卷·释月霞传〉',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4196,'person_013','常惺',NULL,NULL,'Changxing',NULL,NULL,'','patriarch',1896,1939,'近现代','月霞长老弟子。继月霞之后主持华严大学，于北京、上海等地弘传华严。曾任闽南佛学院院长。','月霞系',2,NULL,NULL,NULL,'于凌波《中国近现代佛教人物志》、东初《中国佛教近代史》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4197,'person_014','慈舟',NULL,NULL,'Cizhou',NULL,NULL,'','scholar',1877,1958,'近现代','近代华严学者。长期于北京广济寺、济南等地讲说华严。著《华严经普贤行愿品亲闻记》，对《普贤行愿品》在现代的弘扬有重要推动。','慈舟系',1,'["华严经普贤行愿品亲闻记"]',NULL,NULL,'道源《慈舟大师传》（1877-1958）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4198,'person_015','南亭',NULL,NULL,'Nanting',NULL,NULL,'华严莲社第二任住持','patriarch',1900,1982,'近现代','智光法师弟子。1952年与师智光共创台北华严莲社，任第二任住持。长期弘传华严教观，为台湾华严宗发展奠基人。','华严莲社',2,NULL,NULL,NULL,'《南亭和尚全集》册十三〈南亭和尚年谱〉（陈慧剑撰）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4199,'person_016','成一',NULL,NULL,'Chengyi',NULL,'["乘一", "觉因"]','华严莲社第三任住持·华严专宗学院创办人','patriarch',1914,2011,'当代','江苏泰县人。15岁出家。1949年赴台，协助师祖南亭和尚创办华严莲社，1972年继任住持。1975年创办华严专宗学院，以''专修、专研、专弘华严''为宗旨。1985年创立美国华严莲社。著有多部华严学著作。1988年后恢复泰州光孝寺等大陆祖庭。','华严莲社',3,'["成一和尚著作集"]',NULL,NULL,'《成一和尚著作集》、《成一法师传》〔待核〕',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4200,'person_017','贤度',NULL,NULL,'Xiandu',NULL,NULL,'华严莲社第六任住持·华严专宗学院院长','patriarch',1960,NULL,'当代','当代华严宗女性法嗣传承者。成一法师弟子。2005年获印度德里大学哲学博士。推动华严现代化转型：发行《华严乐坛》专辑、AI多媒体文创演绎五十三参。著有《华严学讲义》《华严净土思想与念佛法门》等。','华严莲社',6,'["华严学讲义", "华严净土思想与念佛法门", "大海的印迹：贤度法师传"]',NULL,NULL,'《华严学讲义》(宗教文化出版社 2006)、《大海的印迹：贤度法师传》(有鹿文化 2021)',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4201,'person_018','智光',NULL,NULL,'Zhiguang',NULL,NULL,'华严莲社首任住持','patriarch',1889,1963,'近现代','近代华严学者。台北华严莲社第一任住持（1952年创社），开启台湾华严宗弘传事业。','智光系',1,NULL,NULL,NULL,'范观澜《江淮名剎泰州光孝寺》〈当代僧皇——智光大師〉',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4202,'person_019','梦参',NULL,NULL,'Mengcan',NULL,'["梦参老和尚"]','当代华严弘扬巨擘','practitioner',1915,2017,'当代','当代高僧，临济宗第四十六代。曾于五台山闭关修行多年。晚年大力弘扬《华严经》，讲说全本《八十华严》影响深远。1991年破例为海云继梦剃度（梦中得地藏菩萨示现），赐法名昌一。','临济宗',46,'["华严经讲记（全本）"]',NULL,NULL,'本库 docs/《梦参老和尚_综合深度研究》（多级信源分级标注）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4203,'person_020','胜友',NULL,'Jinamitra','Jinamitra',NULL,NULL,'藏译华严经主译之一','translator',NULL,NULL,'唐','印度译师。与智军（Ye shes sde）、遍照护（Vairocana）约9世纪初将《华严经》译为藏文（德格版Toh 44）。译自中亚于阗原本。',NULL,NULL,'["藏译华严经（Toh 44）"]',NULL,NULL,'藏译《大方广佛华严经》题记（印度胜友、天王菩提、吐蕃智军共译，遍照护复校，据灵隐寺『学处｜除了三大译本〈华严经〉还有哪些版本』2023、《华严经》藏译著录）、德格版甘珠尔目录、《布顿佛教史》、84000 Toh116 引言共译者',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4204,'person_020b','智军','Ye shes sde','Jñānasena','Yeshe De',NULL,NULL,'藏译华严经主译之一','translator',NULL,NULL,'唐','吐蕃著名译师。与印度胜友合作将《华严经》从于阗本译为藏文。为吐蕃王朝佛教翻译事业的核心人物。',NULL,NULL,'["藏译华严经（Toh 44）"]',NULL,NULL,'84000 译注 Toh116（引言主译）、Rhaldi《吐蕃后期的佛教翻译》论文, Bulletin of Tibetology 38 (2002)',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4205,'person_021','高原明昱',NULL,NULL,'Gaoyuan Mingyu',NULL,NULL,'华严宗第二十五世','patriarch',NULL,NULL,'明','明代华严宗祖师，华严宗第二十五世传人。自他起华严法脉兼传慈恩宗（唯识/法相宗），开创''贤首兼慈恩''传承体系。钦因长老等现代传人皆属此高原法系。','华严五祖',25,'["相宗八要解", "明昱诗集"]',NULL,NULL,'周叔迦《中国佛学史》（1930辅仁讲义）及《贤首宗付法师资记》著录高原法系创立（据中华典藏录）；存世著作《相宗八要解》《明昱诗集》（金陵刻经处光绪二十八年刻本等）；明末高僧，生卒不详〔待补〕',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4206,'person_031','应慈',NULL,NULL,'Yingci',NULL,'["应慈法师", "华严座主"]','近代华严座主','patriarch',1873,1965,'近现代','月霞长老师弟。继承月霞遗志，长期在上海等地弘传华严，被尊为''华严座主''。真禅法师之师。平生讲《华严经》多遍。','月霞系',NULL,NULL,NULL,NULL,'于凌波《中国近现代佛教人物志》〈华严座主释应慈〉',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4207,'person_032','了中',NULL,NULL,'Liaozhong',NULL,NULL,'华严莲社第四任住持','patriarch',1932,2022,'当代','华严莲社第四任住持。延续''专研、专修、专弘''华严的莲社传统。','华严莲社',4,NULL,NULL,NULL,'《了中老和尚纪念文集》（台大佛图藏, 2022）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4208,'person_033','净海',NULL,NULL,'Jinghai',NULL,NULL,'华严莲社第五任住持','patriarch',NULL,NULL,'当代','华严莲社第五任住持（华严莲社创社七十周年特刊历任住持表确认）。著有《南传佛教史》（法鼓文化 2014）、《印尼、马来西亚、新加坡、菲律宾四国佛教史》等。','华严莲社',5,'["南传佛教史"]',NULL,NULL,'华严莲社创社七十周年特刊（hy70.dila.edu.tw 历任住持表：第五任净海和尚）、《老实僧本色——净海长老传》（法鼓文化 2020）、自著《南传佛教史》（法鼓文化 2014）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4209,'person_034','明度',NULL,NULL,'Mingdu',NULL,NULL,'华严莲社第七任住持','patriarch',NULL,NULL,'当代','贤度法师之后，续掌华严莲社。贤首宗''明众生本际，悟诸佛果源''演字辈之一。','华严莲社',7,NULL,NULL,NULL,'华严莲社住持传承记录〔待核：无成卷文献〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4210,'person_041','钦因',NULL,NULL,'Qinyin',NULL,'["敬缘钦因祖师"]','贤首宗第四十一世·高原法系第十七世','patriarch',1928,NULL,'当代','台湾树林福慧寺住持。法名敬缘、号钦因，1928年生于北平（俗姓阎）。贤首宗高原法系第四十一世/第十七世传人。2008年8月30日将华严宗（贤首兼慈恩）衣钵传予海云继梦（第四十二世·高原法系第十八世）。另传法嗣予大慧法师、果峻法师、净严法师、宏慧法师等。演字：''明众生本际，悟诸佛果源''。','贤首宗高原法系',41,NULL,NULL,NULL,'大华严寺〈钦因老和上略传〉（huayenworld.org 2021，法名敬缘号钦因、1928年北平生、俗姓阎）、福慧寺〈历代祖师〉、《贤首宗付法师资记》（大华严寺 2008，2008年传法海云继梦），诸源一致',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4211,'person_042','海云继梦',NULL,NULL,'Haiyun Jimeng',NULL,'["昌一", "继梦"]','三脉汇一的当代华严传承者·大华严寺导师','patriarch',1950,NULL,'当代','俗名陈鹤山，台湾宜兰人。中兴大学经济系毕业。1991年于梦参长老座下出家（临济宗第四十七代，法名昌一，号继梦）。2008年受钦因长老传华严宗衣钵（贤首宗第四十二世）。同年得印度胜师子王菩萨传大乘瑜伽行法。汇三脉归一，开创''普贤乘华严宗''，复兴失传八百余年的''东山法门''。现为南投大华严寺导师。建立''无尽藏灯''传灯体系，分四个阶位下传法脉。','普贤乘华严宗',NULL,NULL,NULL,'["临济宗"]','海云继梦《我们只有一个选择》、《传承·奇迹——大乘瑜伽行派付法师资记》(2010)、《非常华严经》(2014)',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4212,'person_043','体佛',NULL,NULL,'Tifo',NULL,NULL,'贤首禅苑','patriarch',NULL,NULL,'当代','钦因长老法嗣之一。创立贤首禅苑，弘扬华严禅法。','贤首宗高原法系',NULL,NULL,NULL,NULL,'电视弘法节目、道场官方网页〔待核：未见成卷传记文献〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4213,'person_044','真禅',NULL,NULL,'Zhenchan',NULL,NULL,'大陆当代华严禅实践者','patriarch',1916,1995,'当代','当代大陆弘扬华严的代表性高僧。''禅宗临济、教在华严、行归地藏普贤''。师承应慈法师。1980年代后在玉佛寺多次主持华严佛七法会，宣讲《普贤行愿品》《十地品》。著有《玉佛丈室集》十集。','临济宗',NULL,'["玉佛丈室集"]',NULL,'["临济宗"]','真禅自著《玉佛丈室集》(十册)',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4214,'person_045','如孝',NULL,NULL,'Ruxiao',NULL,NULL,'华严宗第四十一世法脉传人','scholar',NULL,NULL,'当代','当代华严思想学者。师承星云长老、传印长老、法映长老。十余年研究华严思想当代实践。提出''别教一乘三类体系''''法界十门体系''''八纲体系''等。著有《生命的艺术》《修行的艺术》等丛书。2024年在《三秦宗教》刊发论文。','华严宗',41,'["生命的艺术", "修行的艺术"]',NULL,NULL,'媒体访谈、凤凰网报道〔待核：无成卷文献〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4215,'person_046','雪窦',NULL,NULL,'Xuedou',NULL,NULL,'美国华严莲社','scholar',NULL,NULL,'当代','美国华严莲社相关人员，推动华严教法在海外英语世界的传播。',NULL,NULL,NULL,NULL,NULL,'华严莲社美国分会传承记录〔待考：查无此人，疑与雪窦寺混淆〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4216,'person_050','审祥',NULL,NULL,'Shinshō',NULL,NULL,'日本华严宗初传','patriarch',NULL,742,'唐/日本','新罗僧。来华从法藏学华严。后赴日本，于东大寺宣讲《华严经》，为日本华严宗之初传。','日本华严',1,NULL,NULL,NULL,'《三国佛法传通缘起》(凝然述·CBETA B0186〔已核〕[🔗](https://cbetaonline.dila.edu.tw/B0186))、《华严宗祖师传》〔待核：日本史料·未入CBETA〕',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4217,'person_060','元晓',NULL,NULL,'Wonhyo',NULL,NULL,'新罗华严学僧','scholar',617,686,'唐/新罗','新罗学僧。与义湘同代，二人曾结伴入唐但中途折返。后自悟大乘起信论奥义。著华严经疏、起信论疏，与法藏、慧远并称东亚起信论三大疏。对朝鲜半岛华严思想影响深远。','高丽华严',NULL,'["华严经疏", "大乘起信论疏", "十门和诤论"]',NULL,NULL,'《宋高僧传》《三国遗事》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4218,'person_061','义湘',NULL,NULL,'Uisang',NULL,NULL,'海东华严初祖','patriarch',625,702,'唐/新罗','新罗僧。与元晓结伴入唐求法，元晓中途折返，义湘独至长安从智俨学华严。归国后创浮石寺，被尊为海东华严初祖。','高丽华严',NULL,'["华严一乘法界图", "白花道场发愿文"]',NULL,NULL,'《宋高僧传》《三国遗事》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4219,'person_062','均如',NULL,NULL,'Kyunyŏ',NULL,NULL,'高丽华严学僧','scholar',923,973,'高丽','高丽初期华严学僧。统一高丽华严南北二宗之分歧。著华严经三宝章圆通钞等。早于义天，为高丽华严之前驱。','高丽华严',NULL,'["华严经三宝章圆通钞", "十句章圆通记"]',NULL,NULL,'《均如传》/韩国佛教史（923-973）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4220,'person_070','慧苑',NULL,NULL,'Huiyuan',NULL,NULL,'法藏弟子·华严异解者','scholar',673,743,'唐','法藏上首弟子。著续华严经略疏刊定记，改五教为四教、以十门代十玄。澄观在华严经疏中系统批判其说。慧苑异解是推动澄观集大成的关键思想动力。','华严五祖',NULL,'["续华严经略疏刊定记", "华严旋澓章"]',NULL,NULL,'《华严经传记》/学术研究（约673-743）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4221,'person_080','续法',NULL,NULL,'Xufa',NULL,NULL,'清代华严集大成者','patriarch',1641,1728,'清','清代华严宗最重要弘传者。字柏亭，号灌顶，仁和人。著贤首五教仪系统整理法藏判教；编华严宗佛祖传梳理传承谱系。讲华严经二十余遍，为清代华严学集大成者。','华严五祖',NULL,'["贤首五教仪", "华严宗佛祖传", "法界宗莲花章"]',NULL,NULL,'CBETA 卍续藏 X58《贤首五教仪》、张爱萍论文〈伯亭续法及其《首楞严经灌顶疏》〉',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4222,'person_090','慧光',NULL,NULL,'Huiguang',NULL,NULL,'地论师南道派始祖','scholar',468,537,'北魏','北魏地论师。从勒那摩提学十地经论，开创地论南道派。世称光统律师。其学说经数代传承至智俨、法藏，是为华严宗义学前身。','华严五祖',NULL,'["十地经论疏", "四分律疏"]',NULL,NULL,'《续高僧传》卷二十一·慧光传',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4223,'person_091','子璿',NULL,NULL,'Zixuan',NULL,NULL,'宋代华严学者','scholar',965,1038,'宋','宋代华严重要学者。长水子璿，秀州人。从洪敏学楞严，后谒慧觉禅师悟入。著起信论疏笔削记，兼弘贤首与天台。','华严五祖',NULL,'["起信论疏笔削记", "楞严经义疏注经"]',NULL,NULL,'《补续高僧传》/学术研究（965-1038）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4224,'person_092','持松',NULL,NULL,'Chisong',NULL,NULL,'月霞系法嗣·华严大学校长','patriarch',1894,1972,'近现代','月霞长老弟子。继常惺之后任华严大学校长。兼弘密法，为近代华严与密教兼通的代表人物。著有贤密教衡等。','月霞系',NULL,'["贤密教衡", "华严宗教义始末记"]',NULL,NULL,'持松自著《密教通关》（1936年撰·1939年上海排印·2005年大千出版社重刊；另三民书局《密教通关新校标点本》〔已核〕）、教界《持松法师纪念文集》〔待核：文集未定位〕',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4225,'person_100','释迦牟尼',NULL,'Śākyamuni','Shakyamuni',NULL,NULL,'佛教创始人·华严经教说者','patriarch',-563,-483,'古印度','佛教创始人。据华严宗传统，华严经为释迦成道后最初三七日于菩提树下为法身大士所说。为一切法脉之根源。','印度源流',NULL,NULL,NULL,NULL,'《长阿含经》《大唐西域记》等佛典原典',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4226,'person_101','马鸣',NULL,'Aśvaghoṣa','Ashvaghosha',NULL,NULL,'大乘论师·起信论造者','scholar',80,150,'古印度','古印度大乘佛教论师。传统著录为大乘起信论作者。该论一心二门三大四信五门之说，为华严宗判教与心性论提供了重要理论资源。','印度源流',NULL,'["大乘起信论"]',NULL,NULL,'《马鸣菩萨传》(T50n2046)、鸠摩罗什译〈马鸣传〉',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4227,'person_102','无著',NULL,'Asaṅga','Asanga',NULL,NULL,'瑜伽行派创始人','scholar',310,390,'古印度','古印度瑜伽行派(Yogācāra)创始人。世亲之兄。其唯识学说经世亲十地经论传入汉地，深刻影响地论学派及华严宗法界缘起思想的形成。','印度源流',NULL,'["瑜伽师地论", "摄大乘论"]',NULL,NULL,'《大唐西域记》/学术研究（约310-390）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4228,'person_103','鸠摩罗什',NULL,'Kumārajīva','Kumarajiva',NULL,NULL,'四大译经师之首','translator',344,413,'后秦','龟兹人。后秦弘始三年(401)至长安，主持中国历史上规模最大的译场。译十住经(T0286,即十地品别译)、十住毗婆沙论、法华经等。其译经为华严学在中国的传播提供了关键文本基础。','译师',NULL,'["十住经", "十住毗婆沙论", "中论", "法华经"]',NULL,NULL,'《高僧传》卷二·鸠摩罗什传',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4229,'person_104','菩提流支',NULL,'Bodhiruci','Bodhiruci',NULL,NULL,'十地经论主译','translator',NULL,527,'北魏','北印度人。北魏永平元年(508)至洛阳，与勒那摩提等译世亲十地经论十二卷。此论译出直接催生了南北朝地论学派，被视为华严宗义学之远源。','译师',NULL,'["十地经论"]',NULL,NULL,'《续高僧传》卷一·菩提流支传（载译经自洛及邺至天平二十余年；卒年诸说未定，存527/530等异说，待核）',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4230,'person_105','燃灯佛',NULL,'Dīpaṃkara','Dipankara',NULL,NULL,'授记释迦成佛之过去佛','patriarch',NULL,NULL,'远古印度','梵名Dīpaṃkara。过去无量劫前之佛。据华严经如来名号品及本生经典，燃灯佛曾为释迦牟尼前身授记: 汝于来世当得作佛号释迦牟尼。此为华严经中佛佛相续无尽法界缘起之始。','印度源流',NULL,NULL,NULL,NULL,'《华严经》/佛典',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4231,'person_106','迦叶佛',NULL,'Kāśyapa','Kashyapa',NULL,NULL,'贤劫第三佛·释迦前身之师','patriarch',NULL,NULL,'远古印度','梵名Kāśyapa。贤劫千佛之第三尊，释迦牟尼佛之前一佛。据华严经，释迦成道时十方诸佛各遣菩萨来集，其中包括过去诸佛之法身显现。华严宗以十方三世无尽诸佛构成法界缘起之佛佛相望网络。','印度源流',NULL,NULL,NULL,NULL,'《华严经》/佛典',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4232,'person_107','毗卢遮那佛',NULL,'Vairocana','Vairocana',NULL,NULL,'华严教主·法身本源','patriarch',NULL,NULL,'法身常住','梵名Vairocana，华严经之根本教主。意译光明遍照、大日如来。华严经以毗卢遮那佛法身为宇宙本体，十方三世一切诸佛皆为其化现。华严宗法界缘起、一即一切等核心教义皆围绕毗卢遮那佛法身展开。非历史人物，为华严教义之法身源头。','印度源流',NULL,NULL,NULL,NULL,'《华严经》/佛典',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4233,'person_110','法显',NULL,NULL,'Faxian',NULL,NULL,'西行求法先驱','practitioner',337,422,'东晋','东晋高僧。399年以65岁高龄从长安出发,经河西走廊、西域、中亚至印度,历时14年游历30余国。412年海路归国。著《佛国记》记录印度佛教圣迹,为中国首位完成印度求法之旅的僧人。','求法僧',NULL,'["佛国记(高僧法显传)"]',NULL,NULL,'《高僧传》卷三·法显传',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4234,'person_111','玄奘',NULL,NULL,'Xuanzang',NULL,NULL,'大翻译家·法相宗创始人','translator',602,664,'唐','唐代高僧。629年从长安西行,经西域中亚至印度那烂陀寺,师从戒贤。645年归国携657部梵本,主持译场译经75部1335卷。著《大唐西域记》,创中国法相唯识宗。','求法僧',NULL,'["大唐西域记", "大般若经", "成唯识论"]',NULL,NULL,'《续高僧传》卷四·玄奘传 /《大唐大慈恩寺三藏法师传》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4235,'person_112','义净',NULL,NULL,'Yijing',NULL,NULL,'海上求法僧·译经家','translator',635,713,'唐','唐代高僧。671年从广州乘波斯船经海路至印度,游历那烂陀寺等30余国。695年归国携梵本400余部,译经56部230卷,偏重律藏。著《南海寄归内法传》《大唐西域求法高僧传》。与法显、玄奘并称三大求法僧。','求法僧',NULL,'["南海寄归内法传", "大唐西域求法高僧传"]',NULL,NULL,'《宋高僧传》卷一·义净传',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4236,'person_113','真谛',NULL,'Paramārtha','Paramartha',NULL,NULL,'四大译经师之一','translator',499,569,'梁/陈','西印度优禅尼国人。梁大同十二年(546)来华,值梁末战乱辗转各地译经。译《摄大乘论》《俱舍论》等64部278卷,系统传译瑜伽行派唯识学。与鸠摩罗什、玄奘、义净并称四大译经师。','译师',NULL,'["摄大乘论", "俱舍论", "大乘起信论(重译)"]',NULL,NULL,'《续高僧传》卷一·真谛传',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4237,'person_114','求那跋陀罗',NULL,'Guṇabhadra','Gunabhadra',NULL,NULL,'楞伽经主译','translator',394,468,'刘宋','中印度人。刘宋元嘉十二年(435)经海路至广州,后至建康译经。译《楞伽经》《胜鬘经》《杂阿含经》等52部134卷。其楞伽译本后为禅宗初祖达摩授与二祖慧可,影响禅宗思想深远,亦与华严如来藏思想有深层义学会通。','译师',NULL,'["楞伽阿跋多罗宝经", "胜鬘经", "杂阿含经"]',NULL,NULL,'《高僧传》卷三·求那跋陀罗传',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4238,'person_115','不空',NULL,'Amoghavajra','Amoghavajra',NULL,NULL,'密宗开元三大士之一','translator',705,774,'唐','师子国(斯里兰卡)人,一说北印度人。幼来华师事金刚智。741年赴师子国和印度求法,746年归国携梵本500余部。译《金刚顶经》等密教经典,与善无畏、金刚智并称开元三大士。华严宗密法(秽迹金刚)与此传承有历史关联。','译师',NULL,'["金刚顶经", "大乘密严经"]',NULL,NULL,'《宋高僧传》卷一·不空传',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4239,'person_116','竺法护',NULL,'Dharmarakṣa','Dharmaraksa',NULL,NULL,'敦煌菩萨·大译经家','translator',239,316,'西晋','月氏侨民,世居敦煌。随师游历西域诸国,通晓36国语言。译经149部,包括华严经中《渐备一切智德经》(十地品异译)、《等目菩萨三昧经》(十定品异译)、《如来兴显经》(如来出现品异译)等多部华严单行经。被尊为''敦煌菩萨''。','译师',NULL,'["渐备一切智德经", "如来兴显经", "正法华经"]',NULL,NULL,'《高僧传》卷一·竺法护传',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4240,'person_117','慧超',NULL,'Prajñāvikrama','Hyecho',NULL,NULL,'新罗求法僧','practitioner',704,787,'唐/新罗','新罗僧。约723年从中国出发经海路至印度,游历五天竺佛教圣迹。727年归国后著《往五天竺国传》记录印度、中亚、西域见闻。该书敦煌残卷于1908年为伯希和发现,为研究8世纪中亚印度的珍贵一手文献。','求法僧',NULL,'["往五天竺国传"]',NULL,NULL,'《往五天竺国传》敦煌写本 / 学术研究',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4241,'person_120','善无畏',NULL,'Śubhakarasiṃha','Subhakarasimha',NULL,NULL,'开元三大士之首·密宗初传','translator',637,735,'唐','中印度人,甘露王后裔。716年至长安,玄宗礼为国师。译《大日经》七卷,传胎藏界密法。与金刚智、不空并称开元三大士,为中国密宗奠基人。弟子一行协助译经并著《大日经疏》。','译师',NULL,'["大日经(大毗卢遮那成佛神变加持经)", "苏婆呼童子请问经"]',NULL,NULL,'《宋高僧传》卷二·善无畏传',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4242,'person_121','金刚智',NULL,'Vajrabodhi','Vajrabodhi',NULL,NULL,'开元三大士·金刚界密法','translator',671,741,'唐','南印度摩赖耶国人。719年经海路至广州,次年抵长安。译《金刚顶经》传金刚界密法。与善无畏、不空并称开元三大士。弟子不空继承其法脉,后传入日本成真言宗。','译师',NULL,'["金刚顶瑜伽中略出念诵经", "七俱胝佛母准提大明陀罗尼经"]',NULL,NULL,'《宋高僧传》卷一·金刚智传',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4243,'person_122','一行',NULL,NULL,'Yixing',NULL,NULL,'天文学家·密宗学僧','scholar',683,727,'唐','唐代高僧,俗名张遂。精通天文历算,制《大衍历》。师事善无畏,协助译《大日经》并著《大日经疏》二十卷,为密宗义学之奠基著作。一行亦曾参学禅宗北宗普寂。','译师',NULL,'["大日经疏", "大衍历"]',NULL,NULL,'《宋高僧传》卷五·一行传',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4244,'person_123','慧果',NULL,NULL,'Huiguo',NULL,NULL,'密宗第七祖·青龙寺','patriarch',746,805,'唐','唐代密宗高僧。师事不空,兼承善无畏胎藏界与金刚智金刚界两部密法。住长安青龙寺,为密宗集大成者。日本空海入唐即从慧果受法,归国后创立日本真言宗。','译师',NULL,NULL,NULL,NULL,'《宋高僧传》·慧果传 / 空海《御请来目录》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4245,'person_124','空海',NULL,NULL,'Kūkai','Kūkai',NULL,'日本真言宗开祖·弘法大师','patriarch',774,835,'唐/日本','日本真言宗开祖。804年入唐,于长安青龙寺从慧果受两部密法。806年归国后于高野山开创真言宗。著《十住心论》以华严判教框架判摄显密诸宗,体现密教与华严义学之深层对话。','日本华严',NULL,'["十住心论", "即身成佛义", "秘密曼荼罗十住心论"]',NULL,NULL,'空海《御请来目录》/ 日本佛教史',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4246,'person_125','六师外道',NULL,NULL,'Six heterodox teachers',NULL,NULL,'佛陀时代非佛教思想家','scholar',NULL,NULL,'古印度','与释迦牟尼同时代的六位印度思想家。据《沙门果经》记载:富兰那迦叶(道德否定论)、末伽梨拘舍罗(宿命论)、散若夷毗罗梨子(不可知论)、阿耆多翅舍钦婆罗(唯物论)、迦罗鸠驮迦旃延(原子论)、尼乾陀若提子(耆那教创始人)。佛教教义正是在与这些学派的对话与辩驳中确立的。','印度源流',NULL,NULL,NULL,NULL,'《长阿含经·沙门果经》(DN 2)',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4247,'person_126','成观法师',NULL,NULL,'Cheng Guan',NULL,NULL,'华严宗42世·真言宗53世阿阇梨·大毘卢寺住持','patriarch',1947,NULL,'当代','台北人,台师大英语系毕业(1972),美国德州TCU英研所深造。1988年于纽约庄严寺依天台宗45代显明老和尚出家,同年于基隆海会寺受三坛大戒。1996年于日本高野山入坛受金胎两部大法,得传法灌顶阿阇梨位,为真言宗53世。2010年4月24日于台北福慧寺依钦因长老受华严兼慈恩法脉,为高原法系贤首宗42世。历任台北大毘卢寺住持(1991年创)、美国遍照寺住持。创「新逍遥园译经院」从事佛典注译与英译。','贤首宗高原法系',NULL,'["楞伽经义贯", "大佛顶首楞严经义贯", "大乘百法明门论今注", "唯识三十论颂义贯"]',NULL,NULL,'大毘卢寺法脉记录、百度百科〔待核：无独立学术文献〕',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4248,'person_130','拉克鲁希',NULL,'Lakulīśa','Lakulish',NULL,NULL,'湿婆神第28代化身·Lord Lakulish','patriarch',NULL,NULL,'远古印度','Lord Lakulish。相传为4500年前湿婆神第28代化身,为印度古典瑜伽行法之原始指导者。其传承历经千年,于现代示现指导巴布基大瑜伽士。','大乘瑜伽行法',NULL,NULL,NULL,NULL,'大华严寺系派内传承记录〔待核：无独立史料〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4249,'person_131','巴布基',NULL,NULL,'Babuji',NULL,NULL,'大瑜伽士·Babuji','practitioner',NULL,NULL,'近现代','Babuji(巴布基大瑜伽士)。Lord Lakulish示现指导的大成就者,传承古典瑜伽行法。','大乘瑜伽行法',NULL,NULL,NULL,NULL,'大华严寺系派内传承记录〔待核：无独立史料〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4250,'person_132','普拉梵纳德',NULL,NULL,'Swami Pranavanad',NULL,NULL,'Swami Pranavanad','practitioner',1884,1959,'近现代','Swami Pranavanad。1913年普贤菩萨于印度再度示现,为其传法。开创现代大乘瑜伽行法传承。','大乘瑜伽行法',NULL,NULL,NULL,NULL,'Swami Prabhavananda《The Eternal Companion》(Ramakrishna Order) 等著述',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4251,'person_133','克利普梵纳德',NULL,NULL,'Swami Kripalavanand',NULL,NULL,'Swami Kripalavanand','practitioner',1913,1981,'近现代','Swami Kripalavanand。1932年从普拉梵纳德接法,继续弘扬大乘瑜伽行法。','大乘瑜伽行法',NULL,NULL,NULL,NULL,'大华严寺系派内传承记录〔待核：无独立史料〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4252,'person_134','胜师子王菩萨',NULL,NULL,'Swami Rajarshi Muni',NULL,NULL,'Swami Rajarshi Muni·印度国师','practitioner',1931,2023,'当代','Swami Rajarshi Muni(惹查西牟尼)。1971年从克利普梵纳德接法。1993年Lakulish以灵性形象示现,遂创立LIFE Mission。被尊为印度国师,2019年获印度总理奖。2008年12月于阿弥塔巴市传大乘瑜伽行法灌顶予海云继梦。已圆寂(约2023年)。','大乘瑜伽行法',NULL,NULL,NULL,NULL,'《传承·奇迹——大乘瑜伽行派付法师资记》系派自述〔待核：梦中授法不可独立验证〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4253,'person_140','罗摩克里希纳',NULL,'Rāmakṛṣṇa','Ramakrishna',NULL,NULL,'Ramakrishna·近代印度灵性复兴之源','practitioner',1836,1886,'1836–1886','Ramakrishna Paramahamsa。19世纪印度神秘主义者,加尔各答达克希涅斯瓦尔 Kali 神庙祭司。主张各宗教皆为通向同一真理的路径。其弟子辨喜将吠檀多传向西方。','参考线',NULL,NULL,NULL,NULL,'M. 原著孟语《Shri Shri Ramakrishna Kathamrita》五卷、Nikhilananda 英译《The Gospel of Sri Ramakrishna》(1942)',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4254,'person_141','辨喜',NULL,'Vivekānanda','Swami Vivekananda',NULL,NULL,'Swami Vivekananda·吠檀多西传第一人','practitioner',1863,1902,'1863–1902','Swami Vivekananda。罗摩克里希纳弟子。1893年芝加哥世界宗教议会演讲轰动西方,创立罗摩克里希纳传道会。将瑜伽与吠檀多哲学系统介绍给西方世界。','参考线',NULL,NULL,NULL,NULL,'Swami Vivekananda《The Complete Works of Swami Vivekananda》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4255,'person_142','奥罗宾多',NULL,NULL,'Sri Aurobindo',NULL,NULL,'Sri Aurobindo·整体瑜伽创立者','practitioner',1872,1950,'1872–1950','Sri Aurobindo。早年留学剑桥,后投身印度独立运动。1910年起隐居本地治里,创立整体瑜伽(Integral Yoga)。其「超心智」演化哲学与华严事事无碍有深层对话空间。','参考线',NULL,'["The Life Divine", "Savitri"]',NULL,NULL,'Sri Aurobindo《The Life Divine》《Savitri》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4256,'person_143','拉玛那·马哈希',NULL,'Ramaṇa Maharṣi','Ramana Maharshi',NULL,NULL,'Ramana Maharshi·参问Who am I','practitioner',1879,1950,'1879–1950','Ramana Maharshi。16岁自发证悟自性,后隐居于圣山 Arunachala 终生。以「我是谁」(Who am I?)参问法门教导学人直证自性。其不二论与禅宗「念佛是谁」话头有可比拟处。','参考线',NULL,NULL,NULL,NULL,'《Talks with Sri Ramana Maharshi》《The Collected Works of Ramana Maharshi》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4257,'person_150','寂天',NULL,'Śāntideva','Shantideva',NULL,NULL,'Śāntideva·入菩萨行论造者','scholar',685,763,'8世纪','Śāntideva(寂天)。那烂陀寺学僧,中观学派大师。著《入菩萨行论》(Bodhicaryāvatāra)为印度大乘修行纲领。《华严经·普贤行愿品》与寂天菩萨行思想可互相参照。','参考线',NULL,'["入菩萨行论", "学处集要"]',NULL,NULL,'《入菩萨行论》(Bodhicaryavatara)',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4258,'person_151','阿底峡',NULL,'Atiśa','Atisha',NULL,NULL,'Atiśa·菩提道灯论造者','patriarch',982,1054,'982–1054','Atiśa(阿底峡)。孟加拉人,超戒寺学僧,后应请入藏弘法。著《菩提道灯论》建立三士道次第。噶当派始祖,宗喀巴格鲁派之前身。圆寂于拉萨附近聂塘。','参考线',NULL,'["菩提道灯论"]',NULL,NULL,'阿底峡《菩提道灯论》、《布顿佛教史》著录',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4259,'person_152','宗喀巴','tsong kha pa',NULL,'Tsongkhapa',NULL,NULL,'Tsongkhapa·格鲁派创始人','patriarch',1357,1419,'1357–1419','Tsongkhapa(宗喀巴)。青海人,藏传佛教格鲁派(黄教)创始人。著《菩提道次第广论》系统化阿底峡三士道思想。与华严判教体系(小始终顿圆)有修行阶次上的对比研究价值。','参考线',NULL,'["菩提道次第广论", "密宗道次第广论"]',NULL,NULL,'宗喀巴《菩提道次第广论》《密宗道次第广论》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4260,'person_f01','思元慧三',NULL,NULL,'Huisan',NULL,NULL,'高原法系40世·福慧寺开山','patriarch',1901,1986,'近现代','宛平人，俗姓霍（1901-1986）。北京广善寺第11代住持·1948年赴台，创树林福慧寺（贤首宗/慈恩宗祖庭·唐密秽迹金刚根本道场）。民国37年来台时已47岁，随身仅带一尊华严三圣像。为高原法系在台根本道场开创者；后传法敬缘钦因。','贤首宗高原法系',NULL,NULL,NULL,NULL,'《贤首宗付法师资记》（据中华典藏录，引周叔迦《中国佛学史》：宛平人俗姓霍、1901-1986、任北京广善寺住持、1948年赴台、后传法敬缘钦因）、福慧寺〈历代祖师〉：高原法系第十六世，生卒1901-1986',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4261,'person_f02','体化性果',NULL,NULL,'Tihua',NULL,NULL,'福慧寺第三代住持','patriarch',1950,NULL,'当代','钦因长老法嗣。福慧寺第三代住持。继承贤首宗高原法系在台弘法事业。','贤首宗高原法系',NULL,NULL,NULL,NULL,'福慧寺〈历代祖师〉、贤首宗高原法系传承记录〔待核：谱系自述〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4262,'person_j01','良弁',NULL,NULL,'Rōben',NULL,NULL,'东大寺初代别当','patriarch',689,774,'唐/日本','审祥弟子。东大寺开山。主持《华严经》讲说。','日本华严',NULL,NULL,NULL,NULL,'《元亨释书》《三国佛法传通缘起》（凝然著）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4263,'person_j02','实忠',NULL,NULL,'Jitchū',NULL,NULL,'东大寺二代','patriarch',726,800,'日本','良弁弟子。继承东大寺华严教学。','日本华严',NULL,NULL,NULL,NULL,'《元亨释书》（华严宗章疏并因明录）〔待核：日本史料〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4264,'person_j03','等定',NULL,NULL,'Tōjō',NULL,NULL,'东大寺华严','patriarch',800,870,'日本','日本华严宗传承者。','日本华严',NULL,NULL,NULL,NULL,'《元亨释书》〔待核：日本史料〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4265,'person_j04','圣宝',NULL,NULL,'Shōbō',NULL,NULL,'醍醐寺开山','patriarch',832,909,'日本','理源大师。兼传真言与华严。','日本华严',NULL,NULL,NULL,NULL,'《元亨释书》《三国佛法传通缘起》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4266,'person_j05','观贤',NULL,NULL,'Kanken',NULL,NULL,'东大寺别当','patriarch',853,925,'日本','东大寺华严教学之中兴。','日本华严',NULL,NULL,NULL,NULL,'《元亨释书》（华严宗章疏并因明录）〔待核：日本史料〕',0,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4267,'person_j06','明惠',NULL,NULL,'Myōe',NULL,NULL,'日本华严中兴之祖','patriarch',1173,1232,'日本','日本镰仓时代华严宗中兴之祖。高山寺开山。复兴东大寺华严教学，兼弘戒律与真言。对日本华严宗有再造之功。','日本华严',NULL,'["摧邪轮", "华严缘起"]',NULL,NULL,'《明惠上人传记》(高山寺)、《元亨释书》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4268,'person_j07','凝然',NULL,NULL,'Gyōnen',NULL,NULL,'东大寺学僧','scholar',1240,1321,'日本','日本镰仓时代东大寺学僧。著八宗纲要系统介绍中国八宗要义；著华严法界义镜等。为日本华严教学之集大成者。','日本华严',NULL,'["八宗纲要", "华严法界义镜"]',NULL,NULL,'凝然自著《三国佛法传通缘起》《华严宗要略》、《元亨释书》',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4269,'person_s01','魏道儒',NULL,NULL,'Wei Daoru',NULL,NULL,'中国社科院学部委员','scholar',1955,NULL,'当代','中国社会科学院学部委员、一级研究员、世界宗教研究所研究员。1955年生，河北景县人。著有《中国华严宗通史》（1998初版）、《华严学与禅学》（2011）、《唐宋佛学》（2017）等。','当代学者',NULL,'["中国华严宗通史"]',NULL,NULL,'魏道儒《中国华严宗通史》（江苏古籍出版社 1998年7月初版·国家社科基金青年项目结项；凤凰出版社 2008年修订版）、《华严学与禅学》（宗教文化出版社 2011）、《唐宋佛学》（中国社会科学出版社 2017）；2011年当选中国社会科学院学部委员（中国社科院、中国宗教学术网任职著录）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4270,'person_s02','王颂',NULL,NULL,'Wang Song',NULL,NULL,'北京大学教授','scholar',1965,NULL,'当代','北京大学哲学系（宗教学系）教授、博导，北京大学佛教研究中心主任。1971年生，日本国际佛教大学院大学博士。尤专华严宗的历史与思想及东亚汉文化圈佛教。著有《宋代华严思想研究》（2008）、《日本佛教》《华严法界观门校释研究》等。','当代学者',NULL,'["宋代华严思想研究"]',NULL,NULL,'王颂《宋代华严思想研究》（宗教文化出版社 2008年1月，ISBN 9787801239594，298页）、《日本佛教：自佛教传入至二十世纪》《华严法界观门校释研究》；北京大学哲学系教授、佛教研究中心主任（北大著录制）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4271,'person_s03','邱高兴',NULL,NULL,'Qiu Gaoxing',NULL,NULL,'中国计量大学教授（曾任吉林大学教授）','scholar',1966,NULL,'当代','中国计量大学人文与外语学院教授、院长（1993-1996于中国人民大学获哲学博士，曾任吉林大学哲学系教授）。华严宗、宗密思想与佛教中国化研究。著有《李通玄佛学思想述评》（2001）、《禅源诸诠集都序》校释（2008）、《大乘玄论译注》（1997）等。','当代学者',NULL,'["李通玄佛学思想述评"]',NULL,NULL,'邱高兴《李通玄佛学思想述评》（佛光文化 2001）、《禅源诸诠集都序》校释（中州古籍出版社 2008）、《大乘玄论译注》（佛光出版社 1997）；现任中国计量大学人文与外语学院教授院长（中国计量大学宗教中国化研究院简历著录；1993-1996于中国人民大学读博）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4272,'person_s04','张文良',NULL,NULL,'Zhang Wenliang',NULL,NULL,'中国人民大学教授','scholar',1966,NULL,'当代','中国人民大学哲学院教授、佛教与宗教学理论研究所研究员，日本东京大学博士。专研中国佛教与日本佛教，尤专华严学与禅宗、地论宗。著有《澄观华严思想研究》（日文）、《“批判佛教”的批判》、《〈大乘起信论〉思想史研究》、《涅槃学研究》（2024）等。','当代学者',NULL,'["澄观华严思想研究"]',NULL,NULL,'张文良《澄观华严思想研究》（日文）、《“批判佛教”的批判》、《〈大乘起信论〉思想史研究》；中国人民大学哲学院教授、日本东京大学博士，专研华严学与禅宗（人大著录制）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4273,'person_x01','虚云',NULL,NULL,'Xuyun',NULL,NULL,'禅宗泰斗·兼祧五宗·近代佛教复兴先驱','patriarch',1840,1959,'清-中华人民共和国','虚云老和尚(1840-1959)，近代禅宗第一高僧。一生兼祧临济、曹洞、沩仰、法眼、云门五宗法脉。修复大小寺院八十余处，晚年驻锡云居山真如禅寺。对《楞严经》《华严经》用功极深，其开示中屡引华严义理。1959年圆寂，世寿120岁。','临济宗',NULL,'["参禅要旨", "虚云老和尚法汇", "禅七开示录"]',NULL,'["曹洞宗", "沩仰宗", "法眼宗", "云门宗"]','《虚云和尚年谱》/禅宗史',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4274,'person_x02','净慧',NULL,NULL,'Jinghui',NULL,NULL,'生活禅创立者·虚云法嗣·承五宗法脉','practitioner',1933,2013,'中华人民共和国','净慧长老(1933-2013)，虚云老和尚法嗣，中国佛教协会副会长，河北省佛教协会创会会长。1991年提出「生活禅」理念——将修行落实于生活。任《法音》主编20年。创办柏林禅寺、四祖寺、玉泉寺等道场。2013年圆寂。','临济宗',NULL,'["生活禅钥", "入禅之门", "禅在当下"]',NULL,'["曹洞宗", "沩仰宗", "法眼宗", "云门宗"]','《生活禅钥》、《指月者——净慧长老与生活禅学术研讨会论文集》（李四龙编, 三联 2015）',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "persons" VALUES(4275,'person_x03','南怀瑾',NULL,NULL,'Nan Huaijin',NULL,NULL,'国学大师·禅宗大居士·东西文化摆渡者','scholar',1918,2012,'中华人民共和国','南怀瑾(1918-2012)，浙江温州乐清人。少年习武学文，1943年于峨眉山大坪寺闭关阅藏三年。1949年赴台，着力弘扬儒释道传统文化，讲学六十余年不辍。著作等身（《论语别裁》《老子他说》《禅海蠡测》等60余部），屡引华严经义阐释生命科学与认知科学。倡「身心性命之学」，推动儿童读经运动，兴建太湖大','居士',NULL,'["论语别裁", "老子他说", "禅海蠡测"]',NULL,'["临济宗", "曹洞宗"]','南怀瑾《禅海蠡测》(复旦大学出版社)',1,'2026-10-11 04:34:30','2026-10-11 04:34:30');
INSERT INTO "texts" VALUES(1,'大方广佛华严经（六十华严）',NULL,'Buddhāvataṃsaka-nāma-mahāvaipulya-sūtra','The Avatamsaka Sutra (60-fascicle)','sutra',NULL,'T09n0278','T09n0278',NULL,'not_listed',NULL,NULL,NULL,'东晋','约418-420年',NULL,60,34,'七处八会','最早汉译全本华严。译自支法领从于阗带回的梵本。 三十四品中，《宝王如来性起品》为八十华严之《如来出现品》所替代， 结构亦有调整。六十华严保留了部分更接近早期梵本的表述。
INSERT INTO "texts" VALUES(2,'大方广佛华严经（八十华严）',NULL,'Buddhāvataṃsaka-nāma-mahāvaipulya-sūtra','The Avatamsaka Sutra (80-fascicle)','sutra',NULL,'T10n0279','T10n0279',NULL,'not_listed',NULL,NULL,NULL,'唐','约695-699年',NULL,80,39,'七处九会','目前汉传佛教最通用的华严经版本。武则天从于阗请来梵本， 诏实叉难陀等于洛阳佛授记寺翻译。法藏参与证义。 三十九品，七处九会结构较六十华严完整。 缺藏译本中的《如来华严品》和《普贤宣说品》。
INSERT INTO "texts" VALUES(3,'大方广佛华严经（四十华严）',NULL,'Gaṇḍavyūha-sūtra','The Avatamsaka Sutra (40-fascicle) / The Stem Array','sutra',NULL,'T10n0293','T10n0293',NULL,'not_listed',NULL,NULL,NULL,'唐','约796-798年',NULL,40,1,'单品（入法界品全本）','即《入法界品》的单行全本翻译。内容比六十华严和八十华严中的 《入法界品》更完整。文末附《普贤菩萨行愿赞》，为藏汉佛教 共同尊奉的重要修行文献。善财童子五十三参的故事全本在此。
INSERT INTO "texts" VALUES(4,'佛说兜沙经',NULL,NULL,'The Tusita Sutra','sutra',NULL,'T10n0280',NULL,NULL,'not_listed',NULL,NULL,NULL,'后汉','约167年',NULL,1,NULL,NULL,'《华严经》中最早被翻译为汉文的单行经。 内容对应于八十华严《如来名号品》的一部分。 是最早传入中国的华严系统经典。
INSERT INTO "texts" VALUES(5,'佛说菩萨本业经',NULL,NULL,'Sutra on the Original Works of Bodhisattvas','sutra',NULL,'T10n0281',NULL,NULL,'not_listed',NULL,NULL,NULL,'吴',NULL,NULL,1,NULL,NULL,'净行品别译，无偈颂部分','zh',NULL,0,0,0,0,'2026-09-27 08:00:19','2026-09-27 08:00:19');
INSERT INTO "texts" VALUES(6,'诸菩萨求佛本业经',NULL,NULL,'Sutra on Bodhisattvas Seeking the Buddha''s Original Works','sutra',NULL,'T10n0282',NULL,NULL,'not_listed',NULL,NULL,NULL,'西晋',NULL,NULL,1,NULL,NULL,'净行品别译','zh',NULL,0,0,0,0,'2026-09-27 08:00:19','2026-09-27 08:00:19');
INSERT INTO "texts" VALUES(7,'菩萨十住行道品',NULL,NULL,'Chapter on the Practice Path of the Ten Stages for Bodhisattvas','sutra',NULL,'T10n0283',NULL,NULL,'not_listed',NULL,NULL,NULL,'西晋',NULL,NULL,1,NULL,NULL,'菩萨十住品别译','zh',NULL,0,0,0,0,'2026-09-27 08:00:19','2026-09-27 08:00:19');
INSERT INTO "texts" VALUES(8,'佛说菩萨十住经',NULL,NULL,'Sutra on the Ten Stages of Bodhisattvas','sutra',NULL,'T10n0284',NULL,NULL,'not_listed',NULL,NULL,NULL,'东晋',NULL,NULL,1,NULL,NULL,'菩萨十住品另一别译','zh',NULL,0,0,0,0,'2026-09-27 08:00:19','2026-09-27 08:00:19');
INSERT INTO "texts" VALUES(9,'渐备一切智德经',NULL,NULL,'Gradual Attainment of All-Wisdom Virtue Sutra','sutra',NULL,'T10n0285',NULL,NULL,'not_listed',NULL,NULL,NULL,'西晋','约297年',NULL,5,NULL,NULL,'十地品早期大本别译。竺法护翻译风格古朴','zh',NULL,0,0,0,0,'2026-09-27 08:00:19','2026-09-27 08:00:19');
INSERT INTO "texts" VALUES(10,'十住经',NULL,NULL,'The Dashabhumika Sutra (Ten Stages Sutra)','sutra',NULL,'T10n0286',NULL,NULL,'not_listed',NULL,NULL,NULL,'姚秦','约402-412年',NULL,4,NULL,NULL,'十地品的重要别译。鸠摩罗什译本流畅易读。 与《十地经论》（世亲造，菩提流支译）注解对象高度对应。 是研究华严经在印度流传形态的重要依据。
INSERT INTO "texts" VALUES(11,'佛说十地经',NULL,NULL,'The Buddha Speaks the Dashabhumika Sutra','sutra',NULL,'T10n0287',NULL,NULL,'not_listed',NULL,NULL,NULL,'唐','约785-805年',NULL,9,NULL,NULL,'十地品晚唐别译。篇幅较大（9卷），与鸠摩罗什的4卷本和内典有出入','zh',NULL,0,0,0,0,'2026-09-27 08:00:19','2026-09-27 08:00:19');
INSERT INTO "texts" VALUES(12,'等目菩萨所问三昧经',NULL,NULL,'Sutra of the Samadhi Asked by Equal-Eye Bodhisattva','sutra',NULL,'T10n0288',NULL,NULL,'not_listed',NULL,NULL,NULL,'西晋',NULL,NULL,3,NULL,NULL,'十定品别译','zh',NULL,0,0,0,0,'2026-09-27 08:00:19','2026-09-27 08:00:19');
INSERT INTO "texts" VALUES(13,'显无边佛土功德经',NULL,NULL,'Sutra Revealing the Merits of Immeasurable Buddha Lands','sutra',NULL,'T10n0289',NULL,NULL,'not_listed',NULL,NULL,NULL,'唐',NULL,NULL,1,NULL,NULL,'寿量品别译。玄奘译，文体精严','zh',NULL,0,0,0,0,'2026-09-27 08:00:19','2026-09-27 08:00:19');
INSERT INTO "texts" VALUES(14,'佛说较量一切佛刹功德经',NULL,NULL,'Sutra on Comparing the Merits of All Buddha Fields','sutra',NULL,'T10n0290',NULL,NULL,'not_listed',NULL,NULL,NULL,'宋',NULL,NULL,1,NULL,NULL,'与寿量品教义相关但不完全对应，属同类题材','zh',NULL,0,0,0,0,'2026-09-27 08:00:19','2026-09-27 08:00:19');
INSERT INTO "texts" VALUES(15,'佛说如来兴显经',NULL,NULL,'Sutra on the Arising and Manifestation of the Tathagata','sutra',NULL,'T10n0291',NULL,NULL,'not_listed',NULL,NULL,NULL,'西晋',NULL,NULL,4,NULL,NULL,'如来性起/出现品的早期大本别译','zh',NULL,0,0,0,0,'2026-09-27 08:00:19','2026-09-27 08:00:19');
