INSERT INTO "locations" VALUES(1321,'l_changan_t','长安逍遥园',NULL,34.26,108.92,'temple','后秦',NULL,NULL,'鸠摩罗什译场所在。后秦姚兴为罗什建,八百沙门参与译经。','["person_103"]','《高僧传》卷二《鸠摩罗什传》（罗什于长安逍遥园草堂寺译经，CBETA T2059）','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1322,'l_changan_x','长安大慈恩寺·弘福寺',NULL,34.22,108.96,'temple','唐',NULL,NULL,'玄奘归国后译场所在。大慈恩寺大雁塔为贮藏梵本所建。','["person_111"]','《大慈恩寺三藏法师传》（玄奘译经处：先弘福寺、后大慈恩寺，CBETA T2053）','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1323,'l_f','台北福慧寺','新北市树林福慧寺',24.98,121.42,'temple','当代','新北市','台湾省','钦因长老住持。2010年成观法师于此受华严兼慈恩法脉。','["person_041", "person_043", "person_126"]','树林福慧寺（台北县树林/今新北市树林区三兴路77号）：慧三长老1955年开山创建，为贤首宗兼慈恩宗祖庭与唐密秽迹金刚法根本道场（福慧寺官网 fuhuisih.org）；现住持体化法师（2013年10月接任）。大华严寺官网 huayenworld.org〈师公-钦因老和上略传〉载：钦因长老2008年9月传贤首兼慈恩宗法脉予海云继梦，为贤首宗兼慈恩宗第四十二世祖位并创大华严寺法系；成观法师于2010年4月24日在此受贤首兼慈恩宗第四十二世法脉（见成观法师《华严法门集要》序·abtemple.org）。','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1324,'l_ganden','拉萨·甘丹寺',NULL,29.75,91.47,'temple','明',NULL,NULL,'宗喀巴1409年创建。格鲁派根本道场。','["person_152"]','《宗喀巴：创建格鲁派》（谢志斌·西北大学，中国藏学研究中心/中国民族报 2022）：宗喀巴1409年建格鲁派第一寺','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1325,'l_guangzhou','广州',NULL,23.13,113.26,'region','历代',NULL,NULL,'海上丝绸之路起点。义净671年从此出发赴印度。','["person_112"]','近现代佛教史料（六祖慧能·禅宗南传地域泛称）','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1326,'l_h','南投大华严寺',NULL,23.92,120.88,'temple','当代',NULL,NULL,'海云继梦导师。普贤乘根本道场。','["person_042"]','大华严寺官网（南投鹿谷，海云继梦创建）huayen.world','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1327,'l_kolkata','加尔各答·罗摩克里希纳传道会',NULL,22.57,88.36,'temple','近现代',NULL,NULL,'辨喜于1897年创立。全球吠檀多传播中心。','["person_140", "person_141"]','罗摩克里希纳传道会/贝卢尔寺官网 belurmath.org（辨喜1897年创立）','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1328,'l_kucha','龟兹',NULL,41.7,82.9,'region','古西域',NULL,NULL,'鸠摩罗什故乡。西域佛教重镇,丝绸之路北道枢纽。','["person_103"]','《大唐西域记》卷一·屈支国（龟兹，CBETA T2087）','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1329,'l_nalanda','那烂陀寺',NULL,25.14,85.44,'temple','古印度',NULL,NULL,'古印度佛教最高学府。玄奘、义净等求法僧曾于此留学。无著、世亲于此弘传瑜伽行派。','["person_000b", "person_102", "person_110", "person_111", "person_112"]','《大唐西域记》卷九·摩揭陀国（那烂陀僧伽蓝，CBETA T2087）','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1330,'l_nalanda2','那烂陀寺(参考)',NULL,25.14,85.44,'temple','古印度',NULL,NULL,'寂天与阿底峡曾驻锡于此。7-12世纪印度佛教最高学府。','["person_150", "person_151"]','《大唐西域记》卷九·摩揭陀国（那烂陀僧伽蓝，CBETA T2087）','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1331,'l_nara','奈良东大寺',NULL,34.69,135.84,'temple','唐/日本',NULL,NULL,'日本华严宗本山。审祥首次讲说《华严经》之处。','["person_050", "person_j01", "person_j02"]','东大寺官网 www.todaiji.or.jp（圣武天皇天平年间敕建，卢舍那大佛）','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1332,'l_pondi','印度本地治里·Aurobindo Ashram',NULL,11.94,79.83,'temple','当代',NULL,NULL,'奥罗宾多与The Mother创立道场。整体瑜伽发源地。','["person_142"]','Sri Aurobindo Ashram 官网 sriaurobindoashram.org（1926年奥罗宾多与母亲创立）','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1333,'l_ramana','印度圣山 Arunachala (Tiruvannamalai)',NULL,12.23,79.07,'mountain','当代',NULL,NULL,'拉玛那·马哈希终生隐修之处。每年吸引全球数千求道者朝圣。','["person_143"]','Sri Ramanasramam 官网（阿鲁那查拉圣山·真如圣山）','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1334,'l_yoga','印度阿弥塔巴·LIFE Mission道场',NULL,23.02,72.57,'temple','当代',NULL,'古吉拉特邦','胜师子王菩萨道场。海云继梦2008年12月于此接受大乘瑜伽行法灌顶传法。','["person_042", "person_134"]','印度 LIFE Mission（The Lakulish International Fellowship''s Enlightenment Mission，拉克鲁希国际联谊会·灵性成就使命团）：1993年由大瑜伽士胜师子王菩萨（Swami Rajarshi Muni，尊者惹查西牟尼）创立，注册于印度古吉拉特邦（Gujarat），总部 Rajrajeshwadham（官网 lifemission.org.in / lifemission.co.in）。属印度瑜伽/印度教拉克鲁希（Lakulish）灵性传承机构，非正统佛教僧团道场。大华严寺官网〈源流与传承〉载：胜师子王菩萨2008年力邀海云继梦亲至印度，于年底传法中领受大乘瑜伽行法灌顶与传承；YogaZen〈瑜伽与禅沿革〉载海云和上2008年远赴印度 LIFE Mission 求法、2018年再度亲赴。','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1335,'loc_001','大慈恩寺','大慈恩寺',34.2198,108.9598,'temple','唐','长安（今西安）','陕西省','唐代皇家寺院。法藏曾于此参与译场并讲说华严。','["person_003"]','《宋高僧传》','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1336,'loc_002','终南山','终南山',33.93,108.97,'mountain','唐','长安（今西安）南郊','陕西省','华严宗重要修行圣地。杜顺、智俨、法藏等均曾于此修行或讲法。至相寺位于此山。','["person_001", "person_002", "person_003", "person_103"]','《续高僧传》《佛祖统纪》','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1337,'loc_003','清凉山（五台山）','五台山',39.0306,113.5648,'mountain','唐','忻州市五台县','山西省','文殊菩萨道场，华严经中明指为清凉山。澄观（清凉国师）曾于此著《华严经疏》，''清凉''之号由此而来。华严宗与五台山渊源极深。唐代大华严寺为山中核心华严道场。','["person_004"]','《华严经·诸菩萨住处品》','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1338,'loc_004','圭峰','圭峰山',34.03,108.68,'mountain','唐','长安（今西安）西南','陕西省','宗密晚年住此，世称圭峰大师。','["person_005"]','《宋高僧传》卷六','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1339,'loc_005','方山','方山',38.04,113.21,'mountain','唐','太原市','山西省','李通玄于此处著《新华严经论》。','["person_009"]','《宋高僧传》卷二十二','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1340,'loc_006','杭州慧因寺','慧因高丽寺',30.23,120.13,'temple','宋','杭州市','浙江省','宋代华严中兴道场。净源法师住此弘传华严，高丽义天入宋求法于此。义天归国后送金书《华严经》三种译本供养此寺。世称''华严第一道场''。','["person_010", "person_011"]','《佛祖统纪》','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1341,'loc_007','洛阳佛授记寺','（已毁，洛阳故城）',34.68,112.44,'temple','唐','洛阳','河南省','实叉难陀于此处主持《八十华严》译场。法藏参与证义。','["person_003", "person_007", "person_103"]','《宋高僧传》卷二','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1342,'loc_008','台北华严莲社','华严莲社',25.033,121.565,'temple','当代','台北市','台湾省','现代华严宗弘传中心。南亭法师创立，成一法师、贤度法师相继住持。出版华严典籍、主办国际华严学术研讨。','["person_015", "person_016", "person_017"]','华严莲社资料','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1343,'loc_009','北京广济寺','广济寺',39.923,116.365,'temple','近现代','北京市','北京市','近代华严弘扬重要道场。慈舟法师曾长期于此讲说华严。','["person_014"]','近现代佛教史料','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1344,'loc_010','常熟兴福寺','兴福寺（华严大学旧址）',31.65,120.74,'temple','清','常熟市','江苏省','月霞长老于此处创立华严大学（1914年），开启近现代华严教育之先河。','["person_012"]','近现代佛教史料','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1345,'loc_011','印度那烂陀寺','那烂陀寺遗址 (Nalanda)',25.1355,85.4432,'temple','','比哈尔邦',NULL,'古印度佛教最高学府。《华严经》中善财童子参访的南方诸城中，多参考此地的学术格局。',NULL,'学术研究','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1346,'loc_012','于阗','和田地区',37.11,79.91,'region','唐','和田','新疆维吾尔自治区','古于阗国。藏译《华严经》译自于阗原本。实叉难陀故乡。中亚佛教枢纽，华严经流布关键节点。','["person_007"]','学术研究（《华严经》流传史）','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1347,'loc_013','敦煌','敦煌莫高窟',40.04,94.8,'region','唐','敦煌市','甘肃省','敦煌藏经洞出土华严经写本数百件，包括汉文写本与藏文残片，为版本对勘提供重要实物文献。',NULL,'敦煌学研究','2026-10-11 04:34:30');
INSERT INTO "locations" VALUES(1348,'loc_014','尼泊尔加德满都谷地','加德满都',27.71,85.32,'region','','加德满都',NULL,'现存华严经梵文写本的主要发现地。尼泊尔梵文残卷为华严经源流研究提供了第一手文献。',NULL,'梵文写本研究','2026-10-11 04:34:30');
