INSERT INTO "article_bi_docs" VALUES('shizhu-miaoyan','T09n0279','https://cbetaonline.dila.edu.tw/zh/T09n0279','miaoyan_bi.py',NULL,NULL,'{"article": "shizhu-miaoyan", "title_zh": "世主妙严品会众名号 · 数据报告", "title_en": "Data Report on the Assemblies of the World-Honoring Splendour Chapter", "source": "CBETA T10n0279《華嚴經》卷二·世主妙嚴品（實主娑婆）", "source_url": "https://cbetaonline.dila.edu.tw/zh/T10n0279", "generated_by": "scripts/miaoyan_bi.py ← data/translation/miaoyan_eda.yaml（← miaoyan_eda.py ← miaoyan_assembly.yaml ＋ miaoyan_eda_lexicon.yaml）", "generated_at_source": "scripts/miaoyan_eda.py（源：miaoyan_assembly.yaml + miaoyan_eda_lexicon.yaml）", "disclaimer": {"zh": "⚠️ 体例：本报告为**分析层**产物，非经文陈述。名号之属类、成员、数量出《世主妙严品》（assembly 层）；词素切分、语义域归属、相似度、聚类、相关、模板诸项皆本站析构（EDA 层与 BI 层）。经文自无「十七语义域」「余弦相似度」「轮廓系数」等名目。凡本报告所得，皆可复算而不可直作教义判读；一字一句之义，仍以经文为准。", "en": "⚠️ Convention: this report is an analytical product, not a statement of the sutra. Class membership, names and counts come from the World-Honoring Splendour Chapter (assembly layer); morpheme segmentation, domain assignment, similarity, clustering, correlation and templates are this site''s own analysis (EDA and BI layers). The sutra has no notion of ''seventeen domains'', ''cosine similarity'' or ''silhouette''. Everything here is reproducible but must not be read as doctrinal judgement; for the meaning of words, the sutra remains authoritative."}, "method": {"pipeline_zh": "经文事实（assembly）→ 词素析构（EDA）→ BI 分析（本层）三层分源，逐层可回溯。", "pipeline_en": "Three separated layers — sutra facts (assembly) → morphemic analysis (EDA) → BI analysis (this layer) — each independently traceable.", "determinism_zh": "凡涉随机处，一律以定种线性同余发生器（LCG）取样，禁用 Python random 默认源（其实现版本间可变，会破坏可复现性）。", "determinism_en": "All sampling uses a seeded linear congruential generator (LCG); Python''s random module is deliberately avoided because its implementations vary between versions and would break reproducibility.", "deps_zh": "零新增依赖：协方差特征分解用自实现 Jacobi 旋转，聚类/轮廓/中心性皆自实现，故结果不随第三方库版本而变。", "deps_en": "No new dependencies: eigen-decomposition uses a self-implemented Jacobi rotation, and clustering, silhouette and centrality are all self-implemented, so results do not drift with third-party library versions.", "integrity_zh": "本层不改 EDA 之任何数字，只读 EDA 而另作分析。故 L.101 以来之口径（high/medium/low 三分、low 单级为标注义务）在此原样承继。", "integrity_en": "This layer alters no figure produced by the EDA; it only reads it and adds analysis. The calibers established since L.101 (three confidence grades, low alone carrying the annotation duty) are inherited unchanged."}, "scorecard": {"note": "本记分卡刻意**不给「综合总分」**：加权合成为单一数字须预设权重，而权重无经无据可依，臆造权重即等于臆造结论。故凡须合成为一数处，一律改为分项列示并各标口径。", "note_en": "This scorecard deliberately withholds any composite index: collapsing metrics into a single number requires weights, and weights unsupported by evidence would amount to manufacturing a conclusion. Where a single figure would be wanted, metrics are listed separately with their definitions instead.", "items": [{"key": "classes", "zh": "会众类别数", "en": "Classes", "value": 40.0, "display": "40", "definition": "40 类（经文明列之群类）", "unit": "count"}, {"key": "named_total", "zh": "明列名号数", "en": "Named assemblies", "value": 414.0, "display": "414", "definition": "经文明列之名号总数", "unit": "count"}, {"key": "tokens_total", "zh": "词素位总数", "en": "Token positions", "value": 1877.0, "display": "1,877", "definition": "可析核名切分后之词素位置总数（含多字词一次计一位）", "unit": "count"}, {"key": "tokens_per_name", "zh": "每名平均词素位", "en": "Token positions per name", "value": 4.5338, "display": "4.53", "definition": "词素位 ÷ 名号数 —— 名号之平均「信息长度」", "unit": "dec2"}, {"key": "names_per_class", "zh": "每类平均名号数", "en": "Names per class", "value": 10.35, "display": "10.35", "definition": "名号数 ÷ 类数 —— 群类之平均「列举密度」", "unit": "dec2"}, {"key": "distinct_tokens", "zh": "不同词素数", "en": "Distinct morphemes", "value": 304.0, "display": "304", "definition": "词素表中实际出现之不同词素", "unit": "count"}, {"key": "reuse_rate", "zh": "语汇复用率", "en": "Morpheme reuse rate", "value": 0.838, "display": "83.80%", "definition": "1 − 不同词素 ÷ 词素位 —— 越高则语汇越有限、构词越模板化", "unit": "ratio"}, {"key": "word_rate", "zh": "多字词占比", "en": "Multi-char word rate", "value": 0.0597, "display": "5.97%", "definition": "多字词命中 ÷ 词素位 —— 复名与专名的密度", "unit": "ratio"}, {"key": "high_rate", "zh": "判读确定率", "en": "High-confidence rate", "value": 0.8524, "display": "85.24%", "definition": "high 词素位 ÷ 词素位 —— 「一字一句之义已核定」之比例", "unit": "ratio"}, {"key": "med_rate", "zh": "medium 占比", "en": "Medium-confidence rate", "value": 0.1375, "display": "13.75%", "definition": "medium ÷ 词素位 —— 判读存疑（比较之需），非标注义务", "unit": "ratio"}, {"key": "low_rate", "zh": "low 占比", "en": "Low-confidence rate", "value": 0.0101, "display": "1.01%", "definition": "low ÷ 词素位 —— 唯一「前端须显示〔待考〕」之单级", "unit": "ratio"}, {"key": "unassigned_rate", "zh": "未定域占比", "en": "Unassigned rate", "value": 0.0101, "display": "1.01%", "definition": "未定域段 ÷ 词素位 —— 含专名/音译与罕字，非「待办」", "unit": "ratio"}]}, "funnel": {"note": "本漏斗分**两轨**，不可连读为一轨：轨道一「名号」逐层收窄，轨道二「词素位」逐层收窄；而二轨之间是**扩张**——一名析为多位词素。故「名号 414 < 词素位 1877」并非异常，而是转换之必然结果。若强并为一轨，则扩张之步会被误读为「流失」。又：t3 之流失（medium+low 之和）**不表示数据缺失**，而表示判读存疑之比重；误读为「覆盖率不足」即错解此表。", "note_en": "The funnel has two tracks that must not be read as one: track one (names) narrows, track two (token positions) narrows, and between the two lies an expansion — one name yields several token positions. ''414 names < 1877 positions'' is therefore not an anomaly but the necessary result of the transformation; merging the tracks would make that expansion look like attrition. Further, the loss at t3 (medium plus low) does not indicate missing data but the share of uncertain readings; reading it as a coverage deficit misreads the table.", "conversion": {"tokens_per_name": 4.5338, "zh": "换算因子：每名平均析为几位词素", "en": "conversion factor: mean token positions yielded per name", "no_core": 0}, "track_names": {"zh": "轨道一 · 名号", "en": "Track one — names", "stages": [{"key": "n1", "zh": "经文明列名号", "en": "Named assemblies in the sutra", "n": 414, "pct_of_track": 1.0, "definition": "《世主妙严品》所明列之名号总数（assembly 层经文事实）"}, {"key": "n2", "zh": "有可析之核名", "en": "Names with an analysable core", "n": 414, "pct_of_track": 1.0, "definition": "剥去类尾后尚余有可析之核者；无核者记 ∅（CBETA 省文记号或核与类名全同者）"}]}, "track_tokens": {"zh": "轨道二 · 词素位", "en": "Track two — token positions", "stages": [{"key": "t1", "zh": "词素位", "en": "Token positions", "n": 1877, "pct_of_track": 1.0, "definition": "核名按词素表切分之位置数（多字词一次计一位）"}, {"key": "t2", "zh": "已归语义域", "en": "Assigned to a semantic domain", "n": 1858, "pct_of_track": 0.9899, "definition": "归入十七语义域之一者；未定域者不入"}, {"key": "t3", "zh": "high 判读", "en": "High-confidence reading", "n": 1589, "pct_of_track": 0.8466, "definition": "一字一句之义已核定者"}]}, "reconciliation": {"zh": "**对账**：本层自「逐词素」重算，EDA 之 metrics 为「导入时」统计，二者应当相符；不相符即数据有变或统计口径有别，须查因。", "en": "Reconciliation: this layer recomputes from the segments themselves while the EDA metrics were computed at import time. The two must agree; any gap means the data or the counting basis has changed and must be investigated.", "caveat_zh": "**一处口径之差，须明辨**：EDA 之 lowconf_hits／medconf_hits 统计**全域**（含未定域词素）；本层 high/medium/low 只计**已归域**者。故「归域内 low」少于「全域 low」，二者之差即未定域中之 low。两个数字都对，只是所计之集合不同——混用即错。", "caveat_en": "One counting difference must be made explicit: the EDA lowconf_hits and medconf_hits counts span all token positions including those with unassigned domain, whereas the high/medium/low split here covers assigned positions only. The gap is exactly the low-confidence unassigned positions. Both figures are correct; they simply count different sets, and conflating them would be an error.", "tokens_total": {"bi": 1877, "eda": 1877, "match": true}, "named_total": {"bi": 414, "eda": 414, "match": true}, "no_core": {"bi": 0, "eda": 0, "match": true}, "unassigned_segs": {"bi": 19, "eda": 19, "match": true}, "lowconf_hits": {"bi": 19, "eda": 19, "match": true}, "medconf_hits": {"bi": 258, "eda": 258, "match": true}, "grade_matrix": [{"scope": "assigned", "confidence": "high", "n": 1589}, {"scope": "assigned", "confidence": "low", "n": 16}, {"scope": "assigned", "confidence": "medium", "n": 253}, {"scope": "unassigned", "confidence": "high", "n": 11}, {"scope": "unassigned", "confidence": "low", "n": 3}, {"scope": "unassigned", "confidence": "medium", "n": 5}], "grade_matrix_note_zh": "由此矩阵可直接读出「已归域／未定域」×「high／medium／low」之实数分布；页面须并列此矩阵，以免读者以「归域内 low」冒充「全域 low」。", "grade_matrix_note_en": "This matrix gives the actual counts of assigned/unassigned against high/medium/low; the page must display it so that ''low within assigned'' is never mistaken for ''low overall''."}, "grades": {"high": {"n": 1589, "pct": 0.8552, "zh": "一字一句之义已核定", "en": "reading settled", "duty": "无须标注", "duty_en": "no annotation required"}, "medium": {"n": 253, "pct": 0.1362, "zh": "判读存疑（比较之需）", "en": "reading uncertain (for comparison only)", "duty": "不宜据以定论", "duty_en": "not to be used as settled"}, "low": {"n": 16, "pct": 0.0086, "zh": "底本疑读", "en": "textually doubtful", "duty": "前端须显示〔待考〕", "duty_en": "must display 〔待考〕"}}}, "domain_landscape": {"note": "十七语义域之分布为**语汇层**之分布，非教义权重之分布。域之划分为本站析构之分析工具，经文本身无「十七域」之名目，故本页一切域相关结论均为分析性，不可径作教义判读。", "note_en": "The distribution across the seventeen semantic domains is a distribution over the lexicon, not over doctrine. The domain scheme is an analytical instrument of this site; the sutra itself has no ''seventeen domains''. All domain-based conclusions here are analytical and must not be read as doctrinal judgement.", "rows": [{"rank": 1, "key": "affix", "zh": "冠綴类", "en": "affix", "color": "#a04000", "n": 357, "pct": 0.1902, "cum_pct": 0.1902, "share_of_assigned": 0.1921, "hhi_contrib": 0.036175}, {"rank": 2, "key": "virtue", "zh": "功德类", "en": "merit-virtue", "color": "#27ae60", "n": 329, "pct": 0.1753, "cum_pct": 0.3655, "share_of_assigned": 0.1771, "hhi_contrib": 0.030723}, {"rank": 3, "key": "luminosity", "zh": "光明类", "en": "luminosity", "color": "#f2c14e", "n": 241, "pct": 0.1284, "cum_pct": 0.4939, "share_of_assigned": 0.1297, "hhi_con